package ktanesolver.module.modded.regular.catchphrase;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;
class CatchphraseSolverTest{private final CatchphraseSolver solver=new CatchphraseSolver();
	@Test void calculatesFullTimedSequenceAndProduct(){BombEntity bomb=bomb("A1J2Z3");bomb.setIndicators(new LinkedHashMap<>(Map.of("BOB",true,"CAR",true)));ModuleEntity module=new ModuleEntity();CatchphraseOutput out=solve(bomb,module,new CatchphraseInput(List.of("red","blue","green","orange"),List.of(2,3,4,5,6)));assertThat(out.timingRow()).isEqualTo(9);assertThat(out.presses()).containsExactly(new CatchphraseOutput.Press(1,7),new CatchphraseOutput.Press(2,6),new CatchphraseOutput.Press(4,9),new CatchphraseOutput.Press(3,1));assertThat(out.product()).isEqualTo(720);assertThat(module.getState().get("catchphrasePanelColors")).isEqualTo(List.of("Red","Blue","Green","Orange"));}
	@Test void appliesEmptyPlateAndThirdPanelGeometryRules(){BombEntity bomb=bomb("ABC123");bomb.replacePortPlates(List.of(Set.of()));assertThat(CatchphraseSolver.panelOrder(List.of("YELLOW","YELLOW","BLUE","PURPLE"),bomb)).containsExactly(2,3,0,1);}
	@Test void appliesGreenAndFallbackBranches(){BombEntity bomb=bomb("ABC123");assertThat(CatchphraseSolver.panelOrder(List.of("GREEN","RED","PURPLE","GREEN"),bomb)).containsExactly(2,1,0,3);assertThat(CatchphraseSolver.panelOrder(List.of("YELLOW","YELLOW","ORANGE","PURPLE"),bomb)).containsExactly(0,2,1,3);}
	@Test void rejectsIncompleteOrOutOfRangeObservations(){assertThat(solver.solve(new RoundEntity(),bomb("ABC123"),new ModuleEntity(),new CatchphraseInput(List.of("RED"),List.of(2,3,4,5,6)))).isInstanceOf(SolveFailure.class);assertThat(solver.solve(new RoundEntity(),bomb("ABC123"),new ModuleEntity(),new CatchphraseInput(List.of("RED","RED","RED","RED"),List.of(1,3,4,5,6)))).isInstanceOf(SolveFailure.class);}
	@SuppressWarnings("unchecked")private CatchphraseOutput solve(BombEntity bomb,ModuleEntity module,CatchphraseInput input){return((SolveSuccess<CatchphraseOutput>)solver.solve(new RoundEntity(),bomb,module,input)).output();}private static BombEntity bomb(String serial){BombEntity b=new BombEntity();b.setSerialNumber(serial);return b;}}
